#!/usr/bin/env -S uv run --script
# /// script
# requires-python = ">=3.11"
# dependencies = ["pillow==11.3.0"]
# ///
"""Produce bounded gallery RGBA assets from the committed fictional portraits."""
from pathlib import Path
import hashlib
from PIL import Image

ROOT = Path(__file__).resolve().parents[1]
SIZE = 96


def main():
    lines = ['/* Generated by scripts/generate_avatar_assets.py; do not hand edit. */',
             '#ifndef CUI_GALLERY_AVATARS_H', '#define CUI_GALLERY_AVATARS_H',
             '// clang-format off: generated byte arrays']
    provenance = ['# Avatar derivative assets', '',
                  'Original fictional portrait provenance: [AVATAR_PROVENANCE.md](AVATAR_PROVENANCE.md).',
                  'Generated with Pillow 11.3.0, RGB→RGBA, centered square crop, Lanczos resize',
                  'to 96×96. Circular masking is performed by the public CUI Avatar cache.', '',
                  '| Source | SHA256 | Derivative |', '| --- | --- | --- |']
    for name in ['alex', 'jamie', 'robin']:
        source = ROOT / 'web/assets' / f'avatar-{name}.png'
        with Image.open(source) as original:
            image = original.convert('RGBA')
            side = min(image.size)
            left, top = (image.width-side)//2, (image.height-side)//2
            image = image.crop((left, top, left+side, top+side)).resize((SIZE, SIZE), Image.Resampling.LANCZOS)
        derivative = source.with_name(f'avatar-{name}-96.png')
        image.save(derivative, optimize=True)
        pixels = image.tobytes()
        lines.append(f'static const unsigned char gallery_avatar_{name}[{len(pixels)}] = {{')
        for offset in range(0, len(pixels), 32):
            lines.append('    '+','.join(str(value) for value in pixels[offset:offset+32])+',')
        lines.append('};')
        provenance.append(f'| {source.name} | `{hashlib.sha256(source.read_bytes()).hexdigest()}` | {derivative.name} |')
    lines += ['// clang-format on', '#endif', '']
    (ROOT / 'web/gallery_avatars.h').write_text('\n'.join(lines))
    (ROOT / 'web/assets/AVATAR_DERIVATIVES.md').write_text('\n'.join(provenance)+'\n')


if __name__ == '__main__':
    main()
